import React from 'react';import ImageWithFallback from './ImageWithFallback';
import { resolveItemImage } from '../utils/itemAssets';
export default function SkinDetailModal({skin,onClose,onUpgrade}){if(!skin)return null;const rarity=skin.rarity||'Mil-Spec',value=Number(skin.virtual_value||0),resale=value*.75;const rc=`rarity-${String(rarity).toLowerCase().replace(/\s+/g,'-')}`;return <div className="skin-detail-overlay" role="dialog" aria-modal="true" onClick={onClose}><div className="skin-detail-modal" onClick={e=>e.stopPropagation()}><button className="skin-modal-close" onClick={onClose} aria-label="Fermer">×</button><div className="skin-detail-art"><div className="skin-art-glow"/><ImageWithFallback src={resolveItemImage(skin)} alt={skin.name} className="skin-detail-image"/><div className="skin-art-rarity">{rarity}</div></div><div className="skin-detail-copy"><span className="section-kicker">WELLCASE / SKIN INSPECTOR</span><h2>{skin.name}</h2><div className={`skin-rarity-pill ${rc}`}>{rarity}</div><div className="skin-stat-grid"><div><span>CATÉGORIE</span><strong>{skin.category||'—'}</strong></div><div><span>VALEUR</span><strong>{value.toLocaleString('fr-FR')} €</strong></div><div><span>REVENDABLE 75%</span><strong>{resale.toLocaleString('fr-FR',{minimumFractionDigits:2})} €</strong></div><div><span>FLOAT</span><strong>{skin.float_value!=null?Number(skin.float_value).toFixed(4):'N/A'}</strong></div></div><p className="skin-detail-note">La valeur du skin compte dans ton inventaire de duel. La vente convertit 75% de cette valeur en cash.</p><div className="skin-detail-actions"><button className="skin-secondary" onClick={onClose}>FERMER</button><button className="skin-primary" onClick={onUpgrade}>UPGRADE ↗</button></div></div></div></div>}
